window.CONTENT_DHIKR=[{"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tr":"Subḥān Allāh wa bi-ḥamdih","de":"Preis sei Allah und Lob Ihm.","reward":"Der Gesandte Allahs ﷺ sagte: Wer an einem Tag hundertmal sagt: Preis sei Allah und Lob Ihm, dessen Verfehlungen werden getilgt, selbst wenn sie wie der Schaum des Meeres wären. (Ṣaḥīḥ al-Buḫārī, Nr. 6405)"},{"ar":"الْحَمْدُ لِلَّهِ","tr":"Al-ḥamdu lillāh","de":"Alles Lob gebührt Allah.","reward":"Der Gesandte Allahs ﷺ sagte: Die Reinheit ist die Hälfte des Glaubens, und al-Hamdu lillah füllt die Waagschale. (Ṣaḥīḥ Muslim, Nr. 223)"},{"ar":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ","tr":"Subḥān Allāh, wal-ḥamdu lillāh, wa lā ilāha illallāh, wallāhu akbar","de":"Preis sei Allah, alles Lob gebührt Allah, es gibt keinen Gott außer Allah und Allah ist größer.","reward":"Der Gesandte Allahs ﷺ sagte: Dass ich sage: Subhan Allah, wal-hamdu lillah, wa la ilaha illallah, wallahu akbar, ist mir lieber als alles, worüber die Sonne aufgeht. (Ṣaḥīḥ Muslim, Nr. 2695)"},{"ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Lā ḥawla wa lā quwwata illā billāh","de":"Es gibt weder Macht noch Kraft außer durch Allah.","reward":"Der Gesandte Allahs ﷺ sagte zu Abu Musa al-Ash'ari: Soll ich dich nicht auf einen Schatz aus den Schätzen des Paradieses hinweisen? Ich sagte: Doch, o Gesandter Allahs. Er sagte: La hawla wa la quwwata illa billah. (Ṣaḥīḥ al-Buḫārī, Nr. 4205)"},{"ar":"أَسْتَغْفِرُ اللَّهَ","tr":"Astaghfirullāh","de":"Ich bitte Allah um Vergebung.","reward":"Der Gesandte Allahs ﷺ sagte: Bei Allah, ich bitte Allah gewiss täglich mehr als siebzigmal um Vergebung und wende mich Ihm reumütig zu. (Ṣaḥīḥ al-Buḫārī, Nr. 6307)"},{"ar":"قُلْ هُوَ اللَّهُ أَحَدٌ ۝ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ قُلْ أَعُوذُ بِرَبِّ النَّاسِ","tr":"Al-Muʿawwiḏāt (Sūrat al-Iḫlāṣ, al-Falaq, an-Nās)","de":"Die drei Schutzsuren (Sure 112, 113, 114)","reward":"Der Gesandte Allahs ﷺ sagte: Sprich Qul huwa Allahu ahad und die beiden Schutzsuren, wenn du den Abend und den Morgen erreichst, dreimal; sie werden dir gegen alles genügen. (Sunan Abī Dāwūd, Nr. 5082; Jāmiʿ at-Tirmiḏī, Nr. 3575)"},{"ar":"لَا إِلَهَ إِلَّا اللَّهُ","tr":"Lā ilāha illallāh","de":"Es gibt keinen Gott außer Allah.","reward":"Der Gesandte Allahs ﷺ sagte: Das beste Gedenken ist: La ilaha illallah, und das beste Bittgebet ist: al-Hamdu lillah. (Jāmiʿ at-Tirmiḏī, Nr. 3383)"},{"ar":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfirullāh wa-atūbu ilayh","de":"Ich bitte Allah um Vergebung und kehre reumütig zu Ihm zurück.","reward":"Der Gesandte Allahs ﷺ sagte: O Menschen, wendet euch reumütig an Allah. Gewiss, ich wende mich an einem Tag hundertmal Ihm reumütig zu. (Ṣaḥīḥ Muslim, Nr. 2702)"},{"ar":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ","tr":"Allāhumma ṣalli ʿalā Muḥammad","de":"O Allah, segne Muhammad.","reward":"Der Gesandte Allahs ﷺ sagte: Wer einmal den Segen auf mich spricht, den segnet Allah zehnmal. (Ṣaḥīḥ Muslim, Nr. 408)"},{"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tr":"Lā ilāha illallāhu waḥdahū lā šarīka lah, lahul-mulku wa lahul-ḥamdu, wa huwa ʿalā kulli šay'in qadīr","de":"Es gibt keinen Gott außer Allah allein, Er hat keinen Teilhaber. Sein ist die Herrschaft und Sein das Lob, und Er hat über alle Dinge Macht.","reward":"Der Gesandte Allahs ﷺ sagte: Wer dies zehnmal spricht, ist wie jemand, der vier Seelen von den Nachkommen Ismails befreit hat. (Ṣaḥīḥ al-Buḫārī, Nr. 6404; Ṣaḥīḥ Muslim, Nr. 2693)"},{"ar":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","tr":"Lā ilāha illā Anta subḥānaka innī kuntu minaẓ-ẓālimīn","de":"Es gibt keinen Gott außer Dir! Preis sei Dir! Wahrlich, ich gehörte zu den Ungerechten.","reward":"Der Gesandte Allahs ﷺ sagte: Das Bittgebet von Dhu n-Nun, das er im Bauch des Fisches sprach: Kein muslimischer Mann betet jemals damit um eine Sache, ohne dass Allah sie für ihn erhört. (Jāmiʿ at-Tirmiḏī, Nr. 3505)"},{"ar":"رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا","tr":"Raḍītu billāhi Rabban, wa bil-Islāmi dīnan, wa bi-Muḥammadin nabiyyā","de":"Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad als Propheten.","reward":"Der Gesandte Allahs ﷺ sagte: Wer sagt: Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad als Gesandten, für den ist das Paradies verpflichtend geworden. (Sunan Abī Dāwūd, Nr. 1529)"},{"ar":"سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ","tr":"Subḥān Allāh al-ʿAẓīm wa bi-ḥamdih","de":"Preis sei Allah, dem Allgewaltigen, und Lob Ihm.","reward":"Der Gesandte Allahs ﷺ sagte: Wer sagt: Preis sei Allah, dem Allgewaltigen, und Lob Ihm, dem wird eine Dattelpalme im Paradies gepflanzt. (Jāmiʿ at-Tirmiḏī, Nr. 3464)"},{"ar":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ","tr":"Ḥasbiyallāhu lā ilāha illā Huwa ʿalayhi tawakkaltu wa Huwa Rabbul-ʿaršil-ʿaẓīm","de":"Allah genügt mir. Es gibt keinen Gott außer Ihm. Auf Ihn vertraue ich, und Er ist der Herr des gewaltigen Thrones.","reward":"Überliefert über Abu d-Darda: Wer am Morgen und am Abend siebenmal sagt: Allah genügt mir, es gibt keinen Gott außer Ihm, auf Ihn vertraue ich und Er ist der Herr des gewaltigen Thrones, dem nimmt Allah die Sorgen ab, die ihn bedrücken. (Sunan Abī Dāwūd, Nr. 5081)"}];
window.CONTENT_QUIZ=[{"q":"In welcher Stadt kam der Prophet Muhammad ﷺ zur Welt?","answers":["Mekka al-Mukarrama","Medina al-Munawwara","Die Oase von Taif","Die Stadt Jerusalem"]},{"q":"Wie hieß die leibliche Mutter des Propheten Muhammad ﷺ?","answers":["Amina bint Wahb","Halima as-Sa'diyya","Baraka Umm Ayman","Fatima bint Asad"]},{"q":"Welcher Engel überbrachte dem Propheten Muhammad ﷺ die göttliche Offenbarung?","answers":["Engel Dschibril","Engel Mika'il","Engel Israfil","Engel Azra'il"]},{"q":"Wie hieß die erste Ehefrau des Propheten Muhammad ﷺ?","answers":["Khadidscha bint Chuwailid","Hafsa bint Umar al-Faruq","Sauda bint Zam'a al-Amiriyya","Aischa bint Abi Bakr as-Siddiq"]},{"q":"Wo empfing der Prophet Muhammad ﷺ die allererste Offenbarung des Korans?","answers":["In der Höhle Hira auf dem Berg an-Nur","In der Höhle Thaur südlich von Mekka","Im Vorhof der Kaaba neben dem Brunnen Zamzam","Im Tal von Mina während der Wallfahrt"]},{"q":"Welcher Großvater zog den Propheten Muhammad ﷺ nach dem Tod der Mutter auf?","answers":["Abd al-Muttalib ibn Haschim","Abu Talib ibn Abd al-Muttalib","Az-Zubair ibn Abd al-Muttalib","Al-Harith ibn Abd al-Muttalib"]},{"q":"Welcher enge Gefährte begleitete den Propheten Muhammad ﷺ bei der Hidschra?","answers":["Abu Bakr as-Siddiq","Umar ibn al-Chattab","Uthman ibn Affan","Ali ibn Abi Talib"]},{"q":"In welchem Jahr der christlichen Zeitrechnung fand die Hidschra nach Medina statt?","answers":["Im Jahr 622 nach Christus","Im Jahr 610 nach Christus","Im Jahr 630 nach Christus","Im Jahr 632 nach Christus"]},{"q":"Wie hieß die Amme die den Propheten Muhammad ﷺ in der Wüste stillte?","answers":["Halima as-Sa'diyya","Barakah Umm Ayman","Schaimaa as-Sa'diyya","Fatima bint Asad"]},{"q":"Welchen Beinamen trug der Prophet Muhammad ﷺ bereits vor der Gesandtschaft?","answers":["Al-Amin der Vertrauenswürdige","As-Siddiq der stets Wahrhaftige","Al-Faruq der gerechte Richter","Dhu an-Nurain der Träger zweier Lichter"]},{"q":"Wie hieß die erste große Schlacht zwischen den Muslimen und den Quraisch?","answers":["Die Schlacht von Badr","Die Schlacht von Uhud","Die Grabenschlacht bei Medina","Die Schlacht von Hunain"]},{"q":"Welcher Onkel des Propheten Muhammad ﷺ schützte ihn jahrelang treu in Mekka?","answers":["Abu Talib ibn Abd al-Muttalib","Al-Abbas ibn Abd al-Muttalib","Hamza ibn Abd al-Muttalib","Al-Harith ibn Abd al-Muttalib"]},{"q":"In welchem Lebensjahr befand sich der Prophet Muhammad ﷺ bei Beginn des Prophetentums?","answers":["Im Alter von vierzig Jahren","Im Alter von dreißig Jahren","Im Alter von fünfzig Jahren","Im Alter von zwanzig Jahren"]},{"q":"In welchem Jahr nach der Hidschra erfolgte die friedliche Öffnung Mekkas?","answers":["Im achten Jahr nach der Hidschra","Im sechsten Jahr nach der Hidschra","Im zweiten Jahr nach der Hidschra","Im zehnten Jahr nach der Hidschra"]},{"q":"An welchem Ort wurde der Prophet Muhammad ﷺ nach seinem Ableben beigesetzt?","answers":["Im Zimmer von Aischa in Medina","In der Kaaba von Mekka al-Mukarrama","Auf dem Friedhof al-Baqi in Medina","In der al-Aqsa Moschee in Jerusalem"]},{"q":"Welcher christliche Mönch in Bosra erkannte die Zeichen des Prophetentums?","answers":["Der Mönch Bahira","Der Mönch Sergius","Der Mönch Nestor","Der Gelehrte Kosmas"]},{"q":"In welches Land wanderten verfolgte Muslime aus Mekka zuerst aus?","answers":["Nach Abessinien ins Reich des Negus","In das südarabische Reich Jemen","Nach Oman an den Persischen Golf","In das Stammesgebiet von Bahrain"]},{"q":"Welcher jüdische Stamm beging während der Grabenschlacht Verrat am Vertrag?","answers":["Der Stamm Banu Quraiza","Der Stamm Banu Qainuqa","Der Stamm Banu an-Nadir","Der Stamm Banu Mustaliq"]},{"q":"Welcher Gefährte schlug den Bau eines Schutzgrabens um Medina vor?","answers":["Salman al-Farisi","Ammar ibn Yasir","Bilal al-Habaschi","Suhaib ar-Rumi"]},{"q":"Wer unterschrieb das Abkommen von al-Hudaibiyya aufseiten der Quraisch?","answers":["Suhail ibn Amr","Safwan ibn Umayya","Ikrimah ibn Abi Dschahl","Hakim ibn Hizam"]},{"q":"In welcher Schlacht fiel Hamza ibn Abd al-Muttalib als Märtyrer?","answers":["In der Schlacht von Uhud","In der Schlacht von Badr","In der Schlacht von Hunain","In der Schlacht von Tabuk"]},{"q":"Welcher Verwandte von Khadidscha deutete die erste Offenbarung anhand der Schriften?","answers":["Waraqa ibn Naufal","Zaid ibn Amr ibn Naufal","Umayya ibn Abi as-Salt","Uthman ibn al-Huwairith"]},{"q":"Wer galt zur Zeit des Propheten ﷺ als das Oberhaupt der Heuchler in Medina?","answers":["Abdullah ibn Ubayy ibn Salul","Ka'b ibn al-Aschraf al-Yahudi","Huyayy ibn Achtab an-Nadari","Dhu al-Chuwaisira at-Tamimi"]},{"q":"Welcher Feldzug im Safar 2 n. H. war der erste vom Propheten ﷺ persönlich angeführte?","answers":["Die Ghazwa von al-Abwa oder Waddan","Die Ghazwa von Buwat bei Radwa","Die Ghazwa von Dhu al-Uschaira","Die Ghazwa Safwan bei Badr al-Ula"]},{"q":"Wer wurde vom Propheten ﷺ zum allerersten Gebetsrufer des Islam ernannt?","answers":["Bilal ibn Rabah al-Habaschi","Abu Mahdhura al-Dschumahi","Amr ibn Umm Maktum al-Quraschi","Sa'd ibn A'idh al-Qaraz"]},{"q":"Wer kommandierte die erste Entsendung namens Sariyya Saif al-Bahr im Ramadan 1 n. H.?","answers":["Hamza ibn Abd al-Muttalib","Ubaida ibn al-Harith","Sa'd ibn Abi Waqqas","Zaid ibn Haritha"]},{"q":"Welcher Gefährte überbrachte das Sendschreiben des Propheten ﷺ an Kaiser Heraklios?","answers":["Dihya ibn Chalifa al-Kalbi","Schudscha ibn Wahb al-Asadi","Hatib ibn Abi Balta'a al-Lachmi","Amr ibn Umayya ad-Damri"]},{"q":"Welche zwei großen Stämme verbündeten sich im Jahr 8 n. H. zur Schlacht von Hunain?","answers":["Die Stämme Hawazin und Thaqif","Die Stämme Ghatafan und Sulaim","Die Stämme Kinana und Hudhail","Die Stämme Bakr und Taghlib"]},{"q":"Wer leitete im Auftrag des Propheten ﷺ im Jahr 9 n. H. die erste reine Haddsch-Pilgerfahrt?","answers":["Abu Bakr as-Siddiq","Umar ibn al-Chattab","Ali ibn Abi Talib","Mu'adh ibn Dschabal"]},{"q":"Aus welcher Region stammte die christliche Gesandtschaft die das Abkommen mit Medina schloss?","answers":["Aus dem fruchtbaren Nadschran","Aus dem nördlichen al-Hira","Aus dem syrischen Bosra","Aus dem jemenitischen Sanaa"]}];
window.CONTENT_TEXTS=[{"title":"Die Schlichtung an der Kaaba","text":"Vor Beginn seines Prophetentums beschloss der Stamm der Quraisch, die Kaaba zu renovieren, da sie durch Überschwemmungen baufällig geworden war. Als die Mauern errichtet waren, entstand ein erbitterter Streit: Welcher Clan sollte die Ehre erhalten, den verehrten Schwarzen Stein an seinen Platz zu heben? Mehrere Tage ruhten die Arbeiten, und ein blutiger Konflikt drohte. Schließlich schlug der älteste Ratsherr vor, den ersten Mann entscheiden zu lassen, der das Tor des Heiligtums betritt. Zur Erleichterung aller erschien Muhammad ﷺ, der wegen seiner Aufrichtigkeit geschätzt wurde. Er löste die Krise mit Weitsicht: Er breitete sein Obergewand auf dem Boden aus, legte den Stein in die Mitte und forderte die Anführer aller rivalisierenden Stämme auf, gemeinsam die Ränder des Tuchs anzuheben. Als der Stein an der Mauer ankam, setzte er ﷺ ihn mit den eigenen Händen ein.","question":"Wie verhinderte Muhammad ﷺ, dass sich einer der Stämme bei der Platzierung des Steins benachteiligt fühlte?","options":[{"text":"Er bestimmte den ältesten Ratsherrn dazu, den Stein stellvertretend für alle Clans einzusetzen.","correct":false},{"text":"Er ließ die Stammesführer gemeinsam die Ecken seines ausgebreiteten Gewands anheben, auf dem der Stein lag.","correct":true},{"text":"Er ließ das Los zwischen den Anführern entscheiden, damit das Schicksal gerecht wählte.","correct":false}]},{"title":"Der Prophet ﷺ und der kleine Vogel","text":"Der Prophet Muhammad ﷺ zeichnete sich durch seine feinfühlige Zuneigung zu Kindern aus. Der Gefährte Anas ibn Mālik berichtete, dass der Gesandte Allahs ﷺ ihre Familie oft besuchte. Anas hatte einen kleinen Halbbruder namens Abū ʿUmayr. Der Junge besaß ein winziges Haustier: ein kleines Vögelchen, einen sogenannten Nughayr, an dem er sehr hing. Eines Tages kam der Prophet ﷺ zu Besuch und bemerkte, dass das Kind bedrückt und weinend in einer Ecke saß. Als er ﷺ nach dem Grund fragte, erfuhr er, dass das Vögelchen gestorben war. Anstatt die Gefühle des Kindes abzutun, setzte sich der Gesandte Allahs ﷺ geduldig zu ihm. Er spendete ihm Trost und sprach mit ihm in sanften, heiteren Reimen: „O Abū ʿUmayr, was hat das Vögelchen gemacht?“ Durch diese persönliche Aufmerksamkeit brachte er das traurige Kind wieder zum Lächeln.","question":"Wie reagierte der Prophet Muhammad ﷺ auf die Trauer des kleinen Jungen über den Verlust seines Haustiers?","options":[{"text":"Er setzte sich zu ihm und tröstete ihn mit einfühlsamen, heiteren Reimen auf Augenhöhe.","correct":true},{"text":"Er kaufte dem Jungen auf dem Markt sogleich ein neues Tier, um seinen Schmerz zu lindern.","correct":false},{"text":"Er ermahnte ihn sanft zur Geduld (Ṣabr) und erklärte ihm den natürlichen Kreislauf des Lebens.","correct":false}]},{"title":"Die Trauben im Garten von Ta’if","text":"Nach schweren Enttäuschungen in Mekka reiste der Prophet Muhammad ﷺ in die Stadt Ta’if, um die dortigen Stämme zum Islam einzuladen. Doch die Anführer wiesen ihn hochmütig ab und trieben die Stadtbevölkerung dazu an, ihn mit Steinen zu bewerfen, sodass er blutend fliehen musste. Erschöpft suchte er ﷺ Zuflucht in einem abgelegenen Dattel- und Traubengarten, der den mekkanischen Adligen ʿUtbah und Šaybah gehörte. Als die beiden seinen Zustand sahen, regte sich Mitgefühl. Sie schickten ihren christlichen Diener ʿAddās mit einer Schale frischer Weintrauben zu ihm. Als der Gesandte Allahs ﷺ seine Hand ausstreckte, sprach er vor dem Essen vernehmlich: „Bismillāh“. Der Diener blickte ihn überrascht an und bemerkte, dass die Einheimischen diesen Ausdruck niemals verwendeten. Dies eröffnete ein Gespräch, in dessen Verlauf der Prophet ﷺ Ninive und den rechtschaffenen Propheten Yūnus (Friede sei mit ihm) erwähnte, was den Diener tief ergriff.","question":"Was brachte den Diener ʿAddās im Garten dazu, überrascht ein Gespräch mit dem Propheten ﷺ zu beginnen?","options":[{"text":"Er bemerkte das friedvolle Leuchten auf dem Gesicht des Propheten ﷺ trotz dessen schwerer Verletzungen.","correct":false},{"text":"Der Prophet ﷺ sprach vor dem Verzehr der Trauben die Worte „Bismillāh“ aus.","correct":true},{"text":"Der Prophet ﷺ erkannte sofort die Herkunft des Dieners und sprach ihn gezielt auf dessen christlichen Glauben an.","correct":false}]}];
window.CONTENT_FRAGMENTS={"40:1":[{"end":1,"de":"Ḥā-Mīm.","emoji":"🔤"}],"40:2":[{"end":6,"de":"Die Offenbarung des Buches ist von Allah, dem Allmächtigen, dem Allwissenden,","emoji":"📖"}],"40:3":[{"end":8,"de":"Dem Vergebenden der Sünde und dem Annehmenden der Reue, dem Strengen im Bestrafen, dem Besitzer der Fülle.","emoji":"🤲"},{"end":12,"de":"Es gibt keinen Gott außer Ihm.","emoji":"☝️"},{"end":14,"de":"Zu Ihm ist der Ausgang.","emoji":"↩️"}],"40:4":[{"end":8,"de":"Über die Zeichen Allahs streiten nur diejenigen, die ungläubig sind.","emoji":"🗣️"},{"end":13,"de":"So lasse dich ihr Umherziehen im Land nicht täuschen!","emoji":"🌍"}],"40:5":[{"end":7,"de":"Vor ihnen leugneten bereits das Volk Nūḥs und die Gruppierungen nach ihnen,","emoji":"📜"},{"end":12,"de":"und jede Gemeinschaft hatte vor, sich ihres Gesandten zu bemächtigen.","emoji":"⚔️"},{"end":18,"de":"Und sie stritten mit dem Falschen, um damit die Wahrheit zu widerlegen. Da ergriff Ich sie.","emoji":"💥"},{"end":21,"de":"Wie war da Meine Bestrafung!","emoji":"⚡"}],"40:6":[{"end":10,"de":"Und so hat sich das Wort deines Herrn gegen diejenigen bewahrheitet, die ungläubig sind: dass sie die Gefährten des Feuers sein werden.","emoji":"🔥"}],"40:7":[{"end":13,"de":"Diejenigen, die den Thron tragen, und diejenigen um ihn herum preisen das Lob ihres Herrn, glauben an Ihn und bitten um Vergebung für diejenigen, die glauben:","emoji":"👑"},{"end":24,"de":"Unser Herr, Du umfasst alles an Barmherzigkeit und Wissen; vergib denjenigen, die bereuen und Deinem Weg folgen,","emoji":"🤲"},{"end":27,"de":"und bewahre sie vor der Strafe des Höllenbrandes!","emoji":"🛡️"}],"40:8":[{"end":12,"de":"Unser Herr, lasse sie eingehen in die Gärten von ʿAdn, die Du ihnen versprochen hast, (sie) und wer rechtschaffen ist von ihren Vätern, ihren Gattinnen und ihren Nachkommen.","emoji":"🌳"},{"end":16,"de":"Du bist ja der Allmächtige und Allweise.","emoji":"👑"}],"40:9":[{"end":2,"de":"Und bewahre sie vor den bösen Taten.","emoji":"🛡️"},{"end":8,"de":"Und wen Du an jenem Tag vor den bösen Taten bewahrst, dessen hast Du dich ja erbarmt;","emoji":"🤍"},{"end":12,"de":"und das ist der großartige Erfolg.","emoji":"🏆"}],"40:10":[{"end":15,"de":"Zu denen, die ungläubig sind, wird gewiss ausgerufen werden: Gewiss, Allahs Abscheu ist größer als eure Abscheu vor euch selbst, da ihr zum Glauben aufgerufen wurdet und ungläubig geblieben seid.","emoji":"📢"}],"40:11":[{"end":13,"de":"Sie werden sagen: Unser Herr, Du hast uns zweimal sterben lassen und zweimal lebendig gemacht. Nun bekennen wir unsere Sünden. Gibt es denn einen Weg zum Hinausgelangen?","emoji":"🚪"}],"40:12":[{"end":7,"de":"Dies (geschieht euch), weil ihr, als Allah allein angerufen wurde, ungläubig wart;","emoji":"❌"},{"end":11,"de":"aber wenn Ihm (andere) beigesellt wurden, glaubtet ihr.","emoji":"👥"},{"end":15,"de":"Das Urteil gehört Allah, dem Erhabenen, dem Großen.","emoji":"⚖️"}],"40:13":[{"end":9,"de":"Er ist es, Der euch Seine Zeichen zeigt und euch vom Himmel Versorgung hinabsendet.","emoji":"🌧️"},{"end":14,"de":"Aber bedenken tut es nur, wer sich (Allah reuevoll) zuwendet.","emoji":"↩️"}],"40:14":[{"end":8,"de":"So ruft Allah an, indem ihr Ihm gegenüber aufrichtig in der Religion seid, auch wenn es den Ungläubigen zuwider ist.","emoji":"🤲"}],"40:15":[{"end":16,"de":"(Er ist es,) Der hohe Rangstufen hat, der Herr des Thrones. Er gibt den Geist von Seinem Befehl, wem von Seinen Dienern Er will, damit er vor dem Tag der Begegnung warne,","emoji":"📜"}],"40:16":[{"end":3,"de":"dem Tag, an dem sie vortreten,","emoji":"👥"},{"end":9,"de":"und nichts von ihnen vor Allah verborgen bleibt.","emoji":"👁️"},{"end":12,"de":"Wem gehört die Herrschaft heute?","emoji":"❓"},{"end":15,"de":"Allah, dem Einen, dem Allbezwinger.","emoji":"☝️"}],"40:17":[{"end":6,"de":"Heute wird jeder Seele das vergolten, was sie erworben hat.","emoji":"⚖️"},{"end":9,"de":"Kein Unrecht gibt es heute.","emoji":"🚫"},{"end":13,"de":"Gewiss, Allah ist schnell im Abrechnen.","emoji":"⚡"}],"40:18":[{"end":8,"de":"Und warne sie vor dem Tag der herannahenden (Entscheidung), da die Herzen in der Kehle sitzen, den Gram unterdrückend.","emoji":"⚠️"},{"end":15,"de":"Die Ungerechten haben weder einen warmen Freund noch einen Fürsprecher, dem Gehör geschenkt würde.","emoji":"👤"}],"40:19":[{"end":6,"de":"Er weiß, was die Blicke an Verräterischem tun und was die Brüste verbergen.","emoji":"👁️"}],"40:20":[{"end":3,"de":"Und Allah entscheidet nach der Wahrheit.","emoji":"⚖️"},{"end":10,"de":"Diejenigen aber, die sie anstatt Seiner anrufen, entscheiden nichts.","emoji":"🪨"},{"end":15,"de":"Gewiss, Allah ist der Allhörende, der Allsehende.","emoji":"👂"}],"40:21":[{"end":12,"de":"Sind sie denn nicht auf der Erde umhergereist, so dass sie schauen (konnten), wie das Ende derjenigen war, die vor ihnen waren?","emoji":"🌍"},{"end":30,"de":"Sie waren ja stärker als sie an Kraft und hinterließen mehr Spuren auf der Erde. Da ergriff sie Allah für ihre Sünden; und sie hatten vor Allah keinen Beschützer.","emoji":"🏛️"}],"40:22":[{"end":9,"de":"Dies (geschah deshalb), weil ihre Gesandten mit den klaren Beweisen zu ihnen kamen, sie aber ungläubig blieben; da ergriff sie Allah.","emoji":"📜"},{"end":13,"de":"Gewiss, Er ist Stark und streng im Bestrafen.","emoji":"💥"}],"40:23":[{"end":6,"de":"Und Wir sandten ja bereits Mūsā mit Unseren Zeichen und einer deutlichen Ermächtigung","emoji":"🌊"}],"40:24":[{"end":7,"de":"zu Firʿawn, Hāmān und Qārūn. Da sagten sie: Ein Zauberer, ein verlogener.","emoji":"👑"}],"40:25":[{"end":13,"de":"Als er ihnen nun die Wahrheit von Uns brachte, sagten sie: Tötet die Söhne derjenigen, die mit ihm glauben, und lasst ihre Frauen am Leben.","emoji":"⚔️"},{"end":19,"de":"Aber die List der Ungläubigen geht gewiss verloren.","emoji":"🕸️"}],"40:26":[{"end":7,"de":"Und Pharao sagte: Lasst mich Mūsā töten! Er soll seinen Herrn anrufen!","emoji":"🗡️"},{"end":18,"de":"Ich fürchte nämlich, dass er eure Religion ändert oder dass er auf der Erde Unheil stiftet.","emoji":"⚠️"}],"40:27":[{"end":13,"de":"Und Mūsā sagte: Ich nehme Zuflucht zu meinem Herrn und eurem Herrn vor jedem Hochmütigen, der nicht an den Tag der Abrechnung glaubt.","emoji":"🛡️"}],"40:28":[{"end":19,"de":"Ein gläubiger Mann von den Leuten Pharaos, der seinen Glauben verheimlichte, sagte: Wollt ihr denn einen Mann töten, weil er sagt: Mein Herr ist Allah, wo er doch mit den klaren Beweisen von eurem Herrn zu euch gekommen ist?","emoji":"🗣️"},{"end":24,"de":"Wenn er ein Lügner ist, so geht seine Lüge zu seinen Lasten;","emoji":"🤥"},{"end":31,"de":"wenn er aber die Wahrheit sagt, wird euch etwas von dem treffen, was er euch androht.","emoji":"⚡"},{"end":39,"de":"Gewiss, Allah leitet niemanden recht, wer maßlos und verlogen ist.","emoji":"🚫"}],"40:29":[{"end":14,"de":"O mein Volk, euer ist heute die Herrschaft, da ihr auf der Erde die Oberhand habt. Wer aber wird uns vor Allahs Strenge helfen, wenn sie über uns kommt?","emoji":"👑"},{"end":26,"de":"Pharao sagte: Ich weise euch nur auf das hin, was ich sehe, und ich leite euch nur auf den Weg des rechten Handelns.","emoji":"🗣️"}],"40:30":[{"end":10,"de":"Und derjenige, der glaubte, sagte: O mein Volk, ich fürchte um euch das Gleiche wie den Tag der Gruppierungen,","emoji":"⚠️"}],"40:31":[{"end":9,"de":"wie den gewohnten Zustand des Volkes Nūḥs, der ʿĀd, der Ṯamūd und derjenigen nach ihnen.","emoji":"📜"},{"end":14,"de":"Und Allah will kein Unrecht für die Diener.","emoji":"⚖️"}],"40:32":[{"end":6,"de":"O mein Volk, gewiss, ich fürchte um euch den Tag des gegenseitigen Zurufens,","emoji":"📢"}],"40:33":[{"end":9,"de":"den Tag, an dem ihr den Rücken kehrt und flieht, ohne dass ihr vor Allah einen Schützer hättet.","emoji":"🏃"},{"end":16,"de":"Und wen Allah in die Irre gehen lässt, der hat niemanden, der ihn rechtleitet.","emoji":"🌫️"}],"40:34":[{"end":13,"de":"Und Yūsuf war ja bereits zuvor mit den klaren Beweisen zu euch gekommen. Aber ihr habt nicht aufgehört, über das im Zweifel zu sein, was er euch brachte,","emoji":"📜"},{"end":23,"de":"bis er dann starb und ihr sagtet: Allah wird nach ihm gewiss keinen Gesandten mehr erstehen lassen.","emoji":"⌛"},{"end":30,"de":"So lässt Allah irregehen, wer maßlos und zweiflerisch ist.","emoji":"🌫️"}],"40:35":[{"end":8,"de":"Diejenigen, die über die Zeichen Allahs streiten, ohne dass eine Ermächtigung zu ihnen gekommen wäre,","emoji":"🗣️"},{"end":15,"de":"haben großen Abscheu bei Allah und bei denjenigen, die glauben, erregt.","emoji":"⚠️"},{"end":23,"de":"So versiegelt Allah das Herz eines jeden Hochmütigen, Gewalttätigen.","emoji":"🔒"}],"40:36":[{"end":9,"de":"Und Pharao sagte: O Hāmān, baue mir einen Hochsitz, vielleicht erreiche ich die Zugänge,","emoji":"🏗️"}],"40:37":[{"end":9,"de":"die Zugänge zu den Himmeln, dass ich zum Gott Mūsās emporsteige; gewiss, ich halte ihn für einen Lügner.","emoji":"🌌"},{"end":17,"de":"Und so wurde Pharao sein böses Tun ausgeschmückt, und er wurde vom (rechten) Weg abgehalten.","emoji":"🥀"},{"end":23,"de":"Aber die List Pharaos ging nur zugrunde.","emoji":"🕸️"}],"40:38":[{"end":8,"de":"Und derjenige, der glaubte, sagte: O mein Volk, folgt mir, so leite ich euch auf den Weg des rechten Handelns.","emoji":"🧭"}],"40:39":[{"end":11,"de":"O mein Volk, dieses irdische Leben ist nur Nießbrauch; das Jenseits aber ist die Wohnstätte des Bleibens.","emoji":"⏳"}],"40:40":[{"end":7,"de":"Wer eine böse Tat begeht, dem wird nur mit Gleichwertigem vergolten;","emoji":"⚖️"},{"end":23,"de":"wer aber rechtschaffen handelt, ob Mann oder Frau, und dabei gläubig ist, jene werden in den Paradiesgarten eingehen, wo sie versorgt werden ohne Abrechnung.","emoji":"🌸"}],"40:41":[{"end":9,"de":"O mein Volk, wie kommt es, dass ich euch zur Rettung rufe, während ihr mich zum Feuer ruft?","emoji":"📢"}],"40:42":[{"end":10,"de":"Ihr ruft mich dazu auf, Allah zu verleugnen und Ihm das beizugesellen, wovon ich kein Wissen habe,","emoji":"❌"},{"end":15,"de":"während ich euch zum Allmächtigen, zum Allvergebenden rufe.","emoji":"🤲"}],"40:43":[{"end":13,"de":"Zweifellos gebührt dem, wozu ihr mich ruft, keine Anrufung, weder im Diesseits noch im Jenseits,","emoji":"🪨"},{"end":17,"de":"und unsere Rückkehr ist gewiss zu Allah,","emoji":"↩️"},{"end":22,"de":"und die Maßlosen sind gewiss die Gefährten des Feuers.","emoji":"🔥"}],"40:44":[{"end":4,"de":"So werdet ihr an das denken, was ich euch sage.","emoji":"⏳"},{"end":8,"de":"Und ich überlasse meine Angelegenheit Allah.","emoji":"🤲"},{"end":12,"de":"Gewiss, Allah sieht die Diener wohl.","emoji":"👁️"}],"40:45":[{"end":5,"de":"Da bewahrte ihn Allah vor den Bosheiten ihrer Ränke,","emoji":"🛡️"},{"end":10,"de":"und die Sippe Pharaos umringte die schlimme Strafe:","emoji":"🌊"}],"40:46":[{"end":5,"de":"das Feuer, dem sie morgens und abends vorgeführt werden.","emoji":"🔥"},{"end":13,"de":"Und am Tag, da die Stunde heraufzieht: Lasst die Sippe Pharaos die strengste Strafe erleiden!","emoji":"⚖️"}],"40:47":[{"end":12,"de":"Und wenn sie im Feuer miteinander streiten, da sagen die Schwachen zu denjenigen, die sich hochmütig verhielten: Gewiss, wir waren eure Gefolgsleute;","emoji":"🗣️"},{"end":19,"de":"könnt ihr uns nun einen Teil des Feuers abnehmen?","emoji":"❓"}],"40:48":[{"end":6,"de":"Diejenigen, die sich hochmütig verhielten, sagen: Gewiss, wir befinden uns alle darin.","emoji":"⛓️"},{"end":12,"de":"Gewiss, Allah hat bereits zwischen den Dienern gerichtet.","emoji":"⚖️"}],"40:49":[{"end":13,"de":"Und diejenigen, die im Feuer sind, sagen zu den Wärtern der Hölle: Ruft euren Herrn an, dass Er uns einen Tag von der Strafe erlasse!","emoji":"🔥"}],"40:50":[{"end":6,"de":"Sie sagen: Kamen nicht doch eure Gesandten mit den klaren Beweisen zu euch?","emoji":"❓"},{"end":8,"de":"Sie sagen: Jawohl!","emoji":"🗣️"},{"end":10,"de":"Sie sagen: So ruft an!","emoji":"📢"},{"end":16,"de":"Aber das Rufen der Ungläubigen geht gewiss verloren.","emoji":"🕸️"}],"40:51":[{"end":11,"de":"Gewiss, Wir helfen Unseren Gesandten und denjenigen, die glauben, im irdischen Leben und am Tag, da die Zeugen auftreten,","emoji":"🛡️"}],"40:52":[{"end":5,"de":"dem Tag, an dem den Ungerechten ihre Entschuldigung nicht nützt;","emoji":"🚫"},{"end":10,"de":"und ihnen wird der Fluch zuteil, und ihnen wird die böse Wohnstätte zuteil.","emoji":"🔥"}],"40:53":[{"end":8,"de":"Und Wir gaben bereits Mūsā die Rechtleitung und ließen die Kinder Isrāʾīls die Schrift erben,","emoji":"📜"}],"40:54":[{"end":4,"de":"als Rechtleitung und Ermahnung für diejenigen, die Verstand besitzen.","emoji":"💡"}],"40:55":[{"end":12,"de":"Sei nun standhaft! Gewiss, Allahs Versprechen ist wahr. Und bitte um Vergebung für deine Sünde und preise das Lob deines Herrn am Abend und am frühen Morgen.","emoji":"🤲"}],"40:56":[{"end":17,"de":"Gewiss, diejenigen, die über Allahs Zeichen streiten, ohne dass eine Ermächtigung zu ihnen gekommen wäre, haben in ihren Brüsten nur Hochmut, den sie nicht verwirklichen können.","emoji":"👤"},{"end":19,"de":"So nimm Zuflucht bei Allah;","emoji":"🛡️"},{"end":23,"de":"gewiss, Er ist der Allhörende, der Allsehende.","emoji":"👂"}],"40:57":[{"end":12,"de":"Wahrlich, die Erschaffung der Himmel und der Erde ist größer als die Erschaffung der Menschen. Aber die meisten Menschen wissen nicht.","emoji":"🌌"}],"40:58":[{"end":10,"de":"Nicht gleich sind der Blinde und der Sehende und diejenigen, die glauben und rechtschaffene Werke tun, und der Missetäter.","emoji":"⚖️"},{"end":13,"de":"Wie wenig ihr bedenkt!","emoji":"💭"}],"40:59":[{"end":11,"de":"Gewiss, die Stunde kommt bestimmt, an ihr gibt es keinen Zweifel. Aber die meisten Menschen glauben nicht.","emoji":"⏳"}],"40:60":[{"end":5,"de":"Euer Herr sagt: Ruft Mich an, so erhöre Ich euch.","emoji":"🤲"},{"end":13,"de":"Gewiss, diejenigen, die sich aus Hochmut weigern, Mir zu dienen, werden demütig in die Hölle eingehen.","emoji":"🔥"}],"40:61":[{"end":10,"de":"Allah ist es, Der euch die Nacht gemacht hat, damit ihr in ihr ruht, und den Tag hell.","emoji":"🌙"},{"end":20,"de":"Gewiss, Allah ist voll Huld gegen die Menschen. Aber die meisten Menschen sind nicht dankbar.","emoji":"🌾"}],"40:62":[{"end":10,"de":"Das ist doch Allah, euer Herr, der Schöpfer von allem. Es gibt keinen Gott außer Ihm.","emoji":"☝️"},{"end":12,"de":"Wie lasst ihr euch also abwendig machen?","emoji":"❓"}],"40:63":[{"end":7,"de":"So lassen sich diejenigen abwendig machen, die Allahs Zeichen zu leugnen pflegten.","emoji":"🚫"}],"40:64":[{"end":14,"de":"Allah ist es, Der euch die Erde zu einem festen Grund und den Himmel zu einem Bau gemacht, euch gestaltet und eure Gestalten schön gemacht und euch von den guten Dingen versorgt hat.","emoji":"🌍"},{"end":17,"de":"Das ist doch Allah, euer Herr.","emoji":"👑"},{"end":21,"de":"Segensreich ist Allah, der Herr der Weltenbewohner!","emoji":"✨"}],"40:65":[{"end":10,"de":"Er ist der Lebendige. Es gibt keinen Gott außer Ihm. So ruft Ihn an, indem ihr Ihm gegenüber aufrichtig in der Religion seid.","emoji":"🤲"},{"end":14,"de":"Alles Lob gebührt Allah, dem Herrn der Weltenbewohner.","emoji":"🤍"}],"40:66":[{"end":20,"de":"Sag: Mir ist es untersagt worden, denjenigen zu dienen, die ihr anstatt Allahs anruft, nachdem zu mir die klaren Beweise von meinem Herrn gekommen sind, und mir ist befohlen worden, mich dem Herrn der Weltenbewohner zu unterwerfen.","emoji":"🛑"}],"40:67":[{"end":20,"de":"Er ist es, Der euch aus Erde erschaffen hat, hierauf aus einem Samentropfen, hierauf aus einem Anhängsel. Hierauf lässt Er euch als kleines Kind hervorkommen. Hierauf (lässt Er euch heranwachsen), damit ihr eure Vollkraft erreicht und damit ihr dann Greise werdet","emoji":"🌱"},{"end":25,"de":"– manche von euch werden schon vorher abberufen –","emoji":"⚰️"},{"end":30,"de":"und damit ihr eine festgesetzte Frist erreicht, und auf dass ihr begreifen mögt.","emoji":"⏳"}],"40:68":[{"end":4,"de":"Er ist es, Der lebendig macht und sterben lässt.","emoji":"🔄"},{"end":12,"de":"Wenn Er eine Sache beschließt, so sagt Er zu ihr nur: Sei!, und so ist sie.","emoji":"🗣️"}],"40:69":[{"end":10,"de":"Siehst du nicht diejenigen, die über die Zeichen Allahs streiten, wie sie sich abwenden lassen?","emoji":"❓"}],"40:70":[{"end":7,"de":"Diejenigen, die das Buch und das leugnen, womit Wir Unsere Gesandten gesandt haben;","emoji":"📖"},{"end":9,"de":"sie werden es aber noch erfahren,","emoji":"⚠️"}],"40:71":[{"end":6,"de":"wenn die Fesseln und die Ketten um ihre Hälse gelegt sind und sie gezerrt werden","emoji":"⛓️"}],"40:72":[{"end":6,"de":"ins siedende Wasser und hierauf im Feuer gepeinigt werden.","emoji":"🔥"}],"40:73":[{"end":7,"de":"Hierauf wird zu ihnen gesagt werden: Wo ist das, was ihr beizugesellen pflegtet","emoji":"❓"}],"40:74":[{"end":3,"de":"anstatt Allahs?","emoji":"🪨"},{"end":12,"de":"Sie werden sagen: Sie sind uns entschwunden; nein, vielmehr haben wir vordem gar nichts angerufen.","emoji":"💨"},{"end":17,"de":"So lässt Allah die Ungläubigen irregehen.","emoji":"🌫️"}],"40:75":[{"end":11,"de":"Dies dafür, dass ihr auf der Erde ohne Recht frohlockt und ausgelassen zu sein pflegtet.","emoji":"🎉"}],"40:76":[{"end":5,"de":"Betretet die Tore der Hölle, ewig darin zu bleiben.","emoji":"🚪"},{"end":8,"de":"Wie schlimm ist die Bleibe der Hochmütigen!","emoji":"🥀"}],"40:77":[{"end":5,"de":"Sei nun standhaft! Gewiss, Allahs Versprechen ist wahr.","emoji":"🤲"},{"end":14,"de":"Ob Wir dir nun einen Teil von dem zeigen, was Wir ihnen androhen, oder dich vorher abberufen – zu Uns werden sie zurückgebracht.","emoji":"↩️"}],"40:78":[{"end":14,"de":"Und Wir sandten ja bereits Gesandte vor dir; unter ihnen sind manche, von denen Wir dir berichtet haben, und unter ihnen sind manche, von denen Wir dir nicht berichtet haben.","emoji":"📜"},{"end":23,"de":"Kein Gesandter kann ein Zeichen bringen außer mit Allahs Erlaubnis.","emoji":"☝️"},{"end":32,"de":"Wenn dann Allahs Befehl kommt, wird nach der Wahrheit entschieden, und verloren haben da diejenigen, die (alles) für nichtig erklären.","emoji":"⚖️"}],"40:79":[{"end":9,"de":"Allah ist es, Der euch das Vieh gemacht hat, damit ihr teils auf ihm reitet; und teils ernährt ihr euch von ihm.","emoji":"🐪"}],"40:80":[{"end":12,"de":"Und ihr habt an ihm (allerlei) Nutzen, und damit ihr darauf ein Anliegen erreicht, das in euren Brüsten ist; und auf ihm und auf den Schiffen werdet ihr getragen.","emoji":"🚢"}],"40:81":[{"end":6,"de":"Und Er zeigt euch Seine Zeichen. Welche der Zeichen Allahs wollt ihr denn leugnen?","emoji":"🌌"}],"40:82":[{"end":11,"de":"Sind sie denn nicht auf der Erde umhergereist, so dass sie schauen (konnten), wie das Ende derjenigen war, die vor ihnen waren?","emoji":"🌍"},{"end":25,"de":"Sie waren zahlreicher als sie, und sie hatten mehr Kraft und hinterließen mehr Spuren auf der Erde. Doch nützte ihnen nicht, was sie zu erwerben pflegten.","emoji":"🏛️"}],"40:83":[{"end":15,"de":"Als ihre Gesandten mit den klaren Beweisen zu ihnen kamen, frohlockten sie über das Wissen, das sie hatten, aber es umschloss sie das, worüber sie sich lustig zu machen pflegten.","emoji":"📚"}],"40:84":[{"end":12,"de":"Als sie dann Unsere Strenge sahen, sagten sie: Wir glauben an Allah allein und verleugnen das, was wir Ihm beizugesellen pflegten.","emoji":"⚡"}],"40:85":[{"end":7,"de":"Aber ihr Glaube nützte ihnen nichts mehr, als sie Unsere Strenge sahen.","emoji":"⌛"},{"end":14,"de":"(So ist) Allahs Gesetzmäßigkeit, die schon zuvor an Seinen Dienern vollzogen worden ist;","emoji":"📜"},{"end":17,"de":"und verloren sind da die Ungläubigen.","emoji":"🥀"}]};
window.CONTENT_MUNASABA={"surah":40,"verses":{"40:1":{"t":"Die Sure beginnt mit zwei einzelnen Buchstaben, aus denen auch die arabische Sprache des Qurʾān besteht, und lenkt so die Aufmerksamkeit auf das Wunder dieser Sprache.","q":"Wenn das Buch aus solchen Buchstaben besteht: Woher kommt es?"},"40:2":{"t":"Es ist keine Menschendichtung, sondern herabgesandt von Allah, dem Allmächtigen (niemand kann es aufhalten oder verfälschen), dem Allwissenden (es ist voll von Wissen).","q":"Wie begegnet dieser mächtige Absender den Menschen, die das Buch hören?"},"40:3":{"t":"Wer umkehrt, dem vergibt Er und nimmt seine Reue an, wer hochmütig bleibt, den straft Er streng, und Seine Gunst (Ḏī aṭ-Ṭawl) geht allem voraus. Es gibt keinen Gott außer Ihm, und zu Ihm kehren alle zurück.","q":"Wenn das alles so klar ist: Warum streiten manche trotzdem über dieses Buch?"},"40:4":{"t":"Nicht aus Mangel an Beweisen, sondern nur aus Unglauben. Und ihr Erfolg und ihr Umherreisen in den Ländern soll dich (den Propheten ﷺ) nicht täuschen.","q":"Warum soll ihr Wohlstand nicht täuschen?"},"40:5":{"t":"Weil schon das Volk Nūḥs und die Gruppen nach ihnen genauso leugneten, gegen ihre Gesandten planten und mit Falschem stritten, und dann ergriff Allah sie. „Wie war Meine Strafe?“ bestätigt den Namen „streng im Strafen“ aus Vers 3.","q":"Gilt das nur für die Völker von damals?"},"40:6":{"t":"Nein, genauso steht das Wort deines Herrn auch über die heutigen Leugner fest: Sie sind die Gefährten des Feuers.","q":"Und die Gläubigen, die von diesen Streitenden bedrängt werden: Stehen sie allein da?"},"40:7":{"t":"Nein: Während auf der Erde gestritten wird, preisen die gewaltigsten Geschöpfe, die Träger des Throns und die Engel um ihn, Allah und bitten um Vergebung und Schutz vor der Hölle für die Gläubigen. Ihr Gebet („Du umfasst alles an Barmherzigkeit und Wissen, vergib denen, die bereuen“) greift die Eigenschaften aus Vers 2–3 wieder auf.","q":"Um was bitten die Engel noch? → Antwort auf Seite 2 (Vers 8–9: Eintritt ins Paradies)."},"40:8":{"t":"Nein, die Engel bitten auch um das Gute: den Eintritt in die Gärten von ʿAdn, zusammen mit den rechtschaffenen Vätern, Ehepartnern und Nachkommen. „Rechtschaffen“ zeigt: Verwandtschaft allein ohne Glauben nützt nichts.","q":"Was brauchen die Gläubigen außerdem, um sicher dorthin zu gelangen?"},"40:9":{"t":"Schutz vor den schlechten Taten und ihren Folgen, denn wen Allah an jenem Tag davor bewahrt, dessen hat Er sich erbarmt. Das ist der gewaltige Gewinn, der wahre Gegensatz zum scheinbaren Gewinn der Ungläubigen aus Vers 4.","q":"Und wie ergeht es an jenem Tag den Ungläubigen?"},"40:10":{"t":"Sie verabscheuen sich selbst, doch ihnen wird zugerufen: Allahs Abscheu war noch größer, als ihr im Diesseits zum Glauben gerufen wurdet und ablehntet.","q":"Was tun sie, als sie ihr Verderben sehen?"},"40:11":{"t":"Sie erkennen zu spät an, dass Allah sie zweimal sterben und zweimal leben ließ, gestehen ihre Sünden und fragen: Gibt es einen Weg hinaus?","q":"Warum gibt es für sie keinen Ausweg?"},"40:12":{"t":"Weil sie ablehnten, wenn Allah allein angerufen wurde, aber glaubten, wenn Ihm etwas beigesellt wurde. Deshalb gehört das Urteil Allah, dem Erhabenen, dem Großen.","q":"Hätten sie Allahs Einzigkeit im Diesseits erkennen können?"},"40:13":{"t":"Ja, Er zeigt euch ständig Seine Zeichen und sendet euch Versorgung vom Himmel. Doch nur wer umkehrt, lässt sich ermahnen.","q":"Was folgt daraus für die Gläubigen?"},"40:14":{"t":"Ruft Allah allein an, aufrichtig in der Religion, auch wenn es den Ungläubigen zuwider ist.","q":"Warum gebührt der aufrichtige Dienst nur Ihm?"},"40:15":{"t":"Weil Er über alle Ränge erhaben ist und der Herr des Throns, und weil Er die Offenbarung (ar-Rūḥ, die tote Herzen lebendig macht) auf Seine Gesandten herabsendet, um vor dem Tag der Begegnung zu warnen.","q":"Was geschieht an diesem Tag der Begegnung?"},"40:16":{"t":"Alle treten offen hervor, nichts bleibt Allah verborgen, und Er fragt: „Wem gehört heute die Herrschaft?“ Die Antwort: Allah, dem Einen, dem Allbezwinger, und damit ist das Prahlen der Ungläubigen aus Vers 4 endgültig vorbei.","q":"Was folgt aus dieser Herrschaft? → Antwort auf Seite 3 (Vers 17: vollkommene Gerechtigkeit, jede Seele bekommt ihren Lohn)."},"40:17":{"t":"Vollkommene Gerechtigkeit: Jede Seele bekommt, was sie erworben hat, heute gibt es kein Unrecht, und Allah ist schnell im Abrechnen.","q":"Wenn dieser Tag so gewiss ist: Was soll der Prophet ﷺ tun?"},"40:18":{"t":"Er soll vor dem „Nahenden“ Tag warnen, an dem die Herzen vor Angst bis zur Kehle steigen. Anders als die Gläubigen, für die die Engel bitten (Vers 7–9), haben die Ungerechten weder Freund noch Fürsprecher.","q":"Wie kann ein Urteil ganz ohne Unrecht sein?"},"40:19":{"t":"Nur durch vollkommenes Wissen: Allah kennt selbst den heimlichen, verräterischen Blick und das, was die Herzen verbergen.","q":"Und was ist mit denen, die man neben Allah anruft? Können sie auch urteilen?"},"40:20":{"t":"Allah richtet mit der Wahrheit, die Götzen dagegen können über gar nichts urteilen. Er ist der Allhörende (hört ihr Streiten) und der Allsehende (sieht ihre Taten).","q":"Die Leugner sehen das Jenseits nicht: Gibt es einen Beweis, den sie schon heute sehen können?"},"40:21":{"t":"Ja, die Ruinen früherer Völker auf der Erde: Diese waren stärker und hinterließen mehr Spuren, und trotzdem ergriff Allah sie, und niemand schützte sie. Damit fällt ihr Stolz auf Macht aus Vers 4.","q":"Warum wurden diese Völker vernichtet?"},"40:22":{"t":"Weil ihre Gesandten mit klaren Beweisen kamen und sie trotzdem ungläubig blieben. „Stark, streng im Strafen“ greift Vers 3 wieder auf.","q":"Gibt es ein konkretes Beispiel für einen Gesandten mit klaren Beweisen?"},"40:23":{"t":"Mūsā, gesandt mit Unseren Zeichen und einer deutlichen Vollmacht.","q":"Zu wem wurde er gesandt, und wie reagierten sie?"},"40:24":{"t":"Zu Firʿawn (politische Macht), Hāmān (Macht der Verwaltung und Planung) und Qārūn (Macht des Geldes), und sie antworteten nur mit Beschimpfung: „Ein Zauberer, ein Lügner!“","q":"Was taten sie, als ihre Worte gegen die Wahrheit nicht halfen?"},"40:25":{"t":"Sie griffen zur Gewalt und befahlen, die Söhne der Gläubigen zu töten und die Frauen am Leben zu lassen. Doch jede List der Ungläubigen führt ins Leere.","q":"Was plant Firʿawn als Nächstes? → Antwort auf Seite 4 (Vers 26: Er will Mūsā selbst töten)."},"40:26":{"t":"Er will Mūsā selbst töten („Lasst mich Mūsā töten“, als ob ihn jemand zurückhielte, dabei hat er selbst Angst). Er rechtfertigt es damit, Mūsā würde eure Religion ändern und Unheil im Land stiften.","q":"Wie antwortet Mūsā auf diese Drohung?"},"40:27":{"t":"Nicht mit einer Gegendrohung, sondern mit Gottvertrauen: Er nimmt Zuflucht bei seinem und ihrem Herrn vor jedem Hochmütigen, der nicht an den Tag der Abrechnung glaubt.","q":"Wie beantwortet Allah Mūsās Zufluchtsuche?"},"40:28":{"t":"Allah schickt Hilfe aus Firʿawns eigener Familie: einen Mann, der seinen Glauben verheimlichte. Er argumentiert klug: Wollt ihr einen Mann töten, nur weil er sagt „Mein Herr ist Allah“? Lügt er, trifft es nur ihn, sagt er die Wahrheit, trifft es euch.","q":"Was sagt er ihnen noch, damit sie nicht auf ihre Macht vertrauen?"},"40:29":{"t":"Heute habt ihr die Herrschaft im Land, doch wer hilft uns, wenn Allahs Strafe kommt? Firʿawn hat kein Gegenargument und sagt nur: Ich zeige euch nur, was ich sehe, und führe euch den rechten Weg.","q":"Wie reagiert der Gläubige auf dieses Machtwort?"},"40:30":{"t":"Er lässt sich nicht beirren und warnt: Ich fürchte für euch einen Tag wie den Tag der Gruppierungen (der gleiche Begriff wie in Vers 5).","q":"Wer waren diese Gruppierungen?"},"40:31":{"t":"Das Volk Nūḥs, ʿĀd, Ṯamūd und die nach ihnen, und ihr Untergang war kein Unrecht, denn Allah will kein Unrecht für Seine Diener (vgl. Vers 17).","q":"Droht ihnen nur ein Untergang im Diesseits?"},"40:32":{"t":"Nein, er fürchtet für sie auch den Tag des gegenseitigen Rufens (Yawm at-Tanād), an dem die Menschen in Panik einander zurufen.","q":"Was geschieht an diesem Tag mit ihnen?"},"40:33":{"t":"Sie fliehen und kehren den Rücken, doch niemand schützt sie vor Allah. Und wen Allah (wegen seines Hochmuts) irregehen lässt, den kann niemand rechtleiten.","q":"Gab es in der Geschichte Ägyptens selbst schon ein Beispiel dafür? → Antwort auf Seite 5 (Vers 34: Yūsuf kam zu ihnen, doch sie blieben im Zweifel)."},"40:34":{"t":"Ja: Yūsuf kam schon früher mit klaren Beweisen zu euch, doch ihr bliebt im Zweifel, und als er starb, sagtet ihr: Allah schickt nie wieder einen Gesandten. So lässt Allah den Maßlosen und Zweifelnden irregehen.","q":"Wer sind diese Maßlosen, die immer zweifeln?"},"40:35":{"t":"Es sind die, die über Allahs Zeichen streiten, ohne jeden Beweis (das Hauptthema der Sure aus Vers 4). Das ist bei Allah und den Gläubigen zutiefst verabscheut, und so versiegelt Allah das Herz jedes Hochmütigen und Gewalttätigen.","q":"Wie zeigt sich dieses versiegelte Herz bei Firʿawn?"},"40:36":{"t":"Firʿawn hat kein Gegenargument mehr und lenkt ab: O Hāmān, bau mir einen hohen Turm, damit ich die Zugänge erreiche.","q":"Welche Zugänge will er erreichen, und wozu?"},"40:37":{"t":"Die Zugänge der Himmel, um nach Mūsās Gott zu schauen, doch er gibt selbst zu: „Ich halte ihn für einen Lügner.“ So wurde ihm sein böses Tun schön gemacht, und seine List endet im Verlust.","q":"Wie antwortet der Gläubige auf Firʿawns Anspruch, er führe das Volk den rechten Weg (Vers 29)?"},"40:38":{"t":"Er dreht genau diesen Satz um: Folgt mir, ich leite euch auf den Weg des rechten Handelns.","q":"Warum klammern sich Firʿawn und sein Volk so sehr an ihre Macht?"},"40:39":{"t":"Weil sie das Diesseits für das Ende halten, doch dieses Leben ist nur ein kurzer Genuss, und das Jenseits ist die bleibende Wohnstätte.","q":"Wie wird man im Jenseits belohnt oder bestraft?"},"40:40":{"t":"Eine schlechte Tat wird nur mit ihresgleichen vergolten (Gerechtigkeit), wer aber gläubig ist und Gutes tut, ob Mann oder Frau, kommt ins Paradies und wird dort ohne Abrechnung versorgt (Barmherzigkeit).","q":"Wie beendet der Gläubige seine Rede? → Antwort auf Seite 6 (Vers 41: „Ich rufe euch zur Rettung, ihr ruft mich zum Feuer“)."},"40:41":{"t":"Mit einem schmerzhaften Gegensatz: O mein Volk, ich rufe euch zur Rettung, und ihr ruft mich zum Feuer!","q":"Wozu genau rufen sie ihn, und wozu ruft er sie?"},"40:42":{"t":"Sie rufen ihn, Allah zu verleugnen und Ihm etwas beizugesellen, wovon er kein Wissen hat. Er ruft sie zum Allmächtigen, dem Allvergebenden (wie am Anfang der Sure, Vers 2–3).","q":"Welchen Wert hat das, wozu sie ihn rufen?"},"40:43":{"t":"Ganz sicher keinen: Ihre Götzen haben weder im Diesseits noch im Jenseits irgendeinen Anspruch. Die Rückkehr ist zu Allah, und die Maßlosen sind die Gefährten des Feuers.","q":"Was tut der Gläubige, nachdem er alles gesagt hat und bedroht wird?"},"40:44":{"t":"Er sagt: Ihr werdet euch noch an meine Worte erinnern, und übergibt seine Angelegenheit ganz Allah, denn Allah sieht die Diener.","q":"Wie antwortet Allah auf dieses Gottvertrauen?"},"40:45":{"t":"Sofort: Allah bewahrt ihn vor ihren bösen Plänen, und stattdessen umschließt die schlimme Strafe die Sippe Firʿawns.","q":"Wie sieht diese Strafe aus?"},"40:46":{"t":"Schon jetzt im Grab (Barzaḫ) werden sie morgens und abends dem Feuer vorgeführt, und wenn die Stunde kommt, heißt es: Lasst die Sippe Firʿawns in die strengste Strafe eingehen.","q":"Hört ihr Streiten in der Hölle auf?"},"40:47":{"t":"Nein, sie streiten sogar im Feuer weiter (so endet das Streiten aus Vers 4): Die schwachen Mitläufer sagen zu den Hochmütigen: Wir sind euch gefolgt, nehmt uns einen Teil des Feuers ab!","q":"Was antworten die Hochmütigen?"},"40:48":{"t":"Wir sind alle darin, Allah hat bereits zwischen den Dienern geurteilt. Damit geben die einstigen Mächtigen ihre völlige Machtlosigkeit zu.","q":"An wen wenden sie sich, als auch untereinander keine Hilfe kommt?"},"40:49":{"t":"An die Wächter der Hölle: Bittet euren Herrn, dass Er uns wenigstens einen Tag die Strafe erleichtert. In Vers 11 wollten sie noch ganz hinaus, jetzt nur noch einen einzigen Tag.","q":"Was antworten die Wächter? → Antwort auf Seite 7 (Vers 50: „Kamen nicht eure Gesandten mit klaren Beweisen?“)."},"40:50":{"t":"Sie fragen zurück: Kamen nicht eure Gesandten mit klaren Beweisen? Die Verdammten sagen „Doch“, also antworten die Wächter: Dann ruft selbst, doch das Rufen der Ungläubigen geht ins Leere (wie ihre List in Vers 25).","q":"Die Feinde der Gesandten haben also keinen Beistand. Und die Gesandten selbst?"},"40:51":{"t":"Allah steht Seinen Gesandten und den Gläubigen bei, im Diesseits und an dem Tag, an dem die Zeugen aufstehen.","q":"Und was erwartet die Ungerechten an diesem Tag?"},"40:52":{"t":"Ihre Entschuldigung nützt ihnen nichts, für sie gibt es den Fluch und die schlimme Wohnstätte.","q":"Gibt es ein Beispiel dafür, dass Allah Seinem Gesandten wirklich beisteht?"},"40:53":{"t":"Ja, Mūsā: Allah gab ihm die Rechtleitung und ließ die (einst unterdrückten) Kinder Isrāʾīls die Schrift erben.","q":"Wozu diente diese Schrift?"},"40:54":{"t":"Als Rechtleitung und Mahnung für die, die Verstand besitzen.","q":"Wenn Allahs Beistand so sicher ist: Was soll der Prophet ﷺ gegenüber den Leugnern in Mekka tun?"},"40:55":{"t":"Geduldig sein, denn Allahs Versprechen ist wahr, um Vergebung bitten und seinen Herrn abends und morgens preisen (wie die Thronträger in Vers 7).","q":"Warum streiten die Leugner eigentlich ohne jeden Beweis?"},"40:56":{"t":"In ihren Herzen ist nichts als Hochmut, eine Größe, die sie nie erreichen werden (das Hauptthema aus Vers 4 und 35). Darum suche Zuflucht bei Allah, dem Allhörenden, dem Allsehenden (wie Mūsā in Vers 27).","q":"Wie wird dieser Hochmut zerschlagen?"},"40:57":{"t":"Durch den Blick auf den Kosmos: Die Erschaffung der Himmel und der Erde ist größer als die Erschaffung der Menschen, doch die meisten wissen es nicht.","q":"Sind der, der das erkennt, und der, der es nicht erkennt, gleich?"},"40:58":{"t":"Nein: Der Blinde und der Sehende sind nicht gleich, ebenso wenig der Gläubige, der Gutes tut, und der Übeltäter. Doch wie wenig ihr bedenkt!","q":"Was folgt daraus, dass Allah das Größere (Himmel und Erde) erschaffen hat? → Antwort auf Seite 8 (Vers 59: Die Stunde kommt ganz sicher)."},"40:59":{"t":"Wer das Größere erschaffen hat, kann die Menschen auch wiedererwecken: Die Stunde kommt ganz sicher, doch die meisten Menschen glauben nicht (weil sie blind sind, Vers 58).","q":"Wenn die Stunde sicher kommt: Was ist der Weg zur Rettung?"},"40:60":{"t":"Das Bittgebet: Euer Herr sagt „Ruft Mich an, so erhöre Ich euch“. Wer aber zu hochmütig ist, Ihm zu dienen (also Ihn zu bitten), geht erniedrigt in die Hölle ein.","q":"Warum sollen wir gerade Ihn anrufen?"},"40:61":{"t":"Weil Er für uns sorgt: Er hat die Nacht zum Ruhen und den Tag zum Sehen gemacht. Allah ist voller Huld zu den Menschen, doch die meisten sind nicht dankbar.","q":"Wer ist der, der all das gibt?"},"40:62":{"t":"Das ist Allah, euer Herr, der Schöpfer von allem, es gibt keinen Gott außer Ihm. Wie könnt ihr euch da abwenden lassen?","q":"Ist diese Abwendung etwas Neues?"},"40:63":{"t":"Nein, genauso ließen sich schon früher die abwenden, die Allahs Zeichen leugneten (wie in Vers 5 und 21).","q":"Welche Gaben zeigt Allah noch, außer Tag und Nacht?"},"40:64":{"t":"Die Erde als festen Grund, den Himmel als Bau, eure schöne Gestalt und die guten Dinge als Versorgung. Das ist Allah, euer Herr, segensreich ist Allah, der Herr der Welten.","q":"Was folgt aus all diesen Gaben?"},"40:65":{"t":"Er ist der Lebendige, es gibt keinen Gott außer Ihm, also ruft Ihn aufrichtig an (wörtlich wie Vers 14). Alles Lob gebührt Allah, dem Herrn der Welten.","q":"Was soll der Prophet ﷺ den Götzendienern deshalb klar sagen?"},"40:66":{"t":"Sprich: Mir wurde verboten, dem zu dienen, was ihr neben Allah anruft, da die klaren Beweise zu mir kamen, und mir wurde befohlen, mich dem Herrn der Welten zu ergeben.","q":"Welchen Beweis gibt es direkt im Menschen selbst? → Antwort auf Seite 9 (Vers 67: Er erschuf euch aus Erde, dann aus einem Samentropfen …)."},"40:67":{"t":"Ja, deine eigene Entstehung: aus Erde, dann aus einem Samentropfen, dann aus einem Anhängsel, dann als Kind, dann in voller Kraft, dann als Greis, und manche sterben schon vorher. Niemand kann diesen Ablauf aufhalten, damit ihr begreift.","q":"Wer bestimmt über dieses Leben und Sterben?"},"40:68":{"t":"Er allein macht lebendig und lässt sterben, und das ohne jede Mühe: Wenn Er etwas beschließt, sagt Er nur „Sei!“, und es ist.","q":"Wie kann jemand nach so klaren Beweisen trotzdem streiten?"},"40:69":{"t":"Das ist erstaunlich: Hast du nicht die gesehen, die über Allahs Zeichen streiten, wie sie sich abwenden lassen? (wieder das Hauptthema aus Vers 4)","q":"Wer sind diese Streitenden genau?"},"40:70":{"t":"Die das Buch und die Botschaft aller Gesandten der Lüge bezichtigen, und sie werden es noch erfahren.","q":"Was werden sie erfahren?"},"40:71":{"t":"Fesseln um ihre Hälse und Ketten, an denen sie gezogen werden. Der Hals, der sich nicht vor Allah beugen wollte (Vers 60), wird nun gefesselt.","q":"Wohin werden sie gezogen?"},"40:72":{"t":"Erst in kochendes Wasser, dann werden sie im Feuer angezündet.","q":"Was kommt zur körperlichen Strafe noch dazu?"},"40:73":{"t":"Die beschämende Frage: Wo ist das, was ihr beigesellt habt …","q":"… und was antworten sie?"},"40:74":{"t":"… neben Allah? Sie sagen: Sie sind uns entschwunden, ja, eigentlich riefen wir früher gar nichts an. So lässt Allah die Ungläubigen irregehen.","q":"Was war die Ursache für dieses Ende?"},"40:75":{"t":"Ihr habt euch auf der Erde zu Unrecht gefreut und wart übermütig.","q":"Was ist die Folge davon?"},"40:76":{"t":"Tretet durch die Tore der Hölle ein, für immer, wie schlimm ist die Wohnstätte der Hochmütigen! (Hochmut, das Grundübel wie in Vers 27, 35, 56 und 60)","q":"Und was soll der Prophet ﷺ tun, solange die Leugner noch nicht bestraft sind?"},"40:77":{"t":"Geduldig sein, denn Allahs Versprechen ist wahr (wörtlich wie Vers 55). Ob du einen Teil ihrer Strafe noch erlebst oder vorher stirbst: Zu Uns werden sie zurückgebracht.","q":"Ging es früheren Gesandten genauso? → Antwort auf Seite 10 (Vers 78: Wir sandten schon vor dir Gesandte …)."},"40:78":{"t":"Ja, Allah sandte viele Gesandte vor dir, von manchen hat Er dir berichtet, von anderen nicht, und keiner konnte ein Wunder bringen ohne Allahs Erlaubnis. Wenn Allahs Befehl kommt, wird mit der Wahrheit entschieden, und dort verlieren die Verfechter des Falschen.","q":"Die Leugner fordern Wunder, aber sehen sie nicht die Zeichen, die sie schon jeden Tag haben?"},"40:79":{"t":"Allah hat euch das Vieh gegeben, damit ihr auf einem Teil davon reitet und von einem Teil esst.","q":"Welchen Nutzen haben sie noch davon?"},"40:80":{"t":"Vielerlei Nutzen, und auf ihnen erreicht ihr die Ziele, die ihr euch vornehmt, und auf ihnen und auf den Schiffen werdet ihr getragen (zu Land und zu Wasser).","q":"Was ist die Schlussfolgerung aus all diesen täglichen Zeichen?"},"40:81":{"t":"Er zeigt euch ständig Seine Zeichen, also welche der Zeichen Allahs wollt ihr denn leugnen?","q":"Und wenn sie trotzdem leugnen: Was lehrt die Geschichte?"},"40:82":{"t":"Schaut euch auf der Erde das Ende der früheren Völker an: Sie waren zahlreicher, stärker und hinterließen mehr Spuren, doch nichts davon nützte ihnen (fast wortgleich mit Vers 21).","q":"Warum lehnten diese Völker ihre Gesandten ab?"},"40:83":{"t":"Weil sie sich über ihr eigenes weltliches Wissen freuten und meinten, die Offenbarung nicht zu brauchen, und so traf sie genau das, worüber sie spotteten.","q":"Was sagten sie, als die Strafe dann vor ihren Augen stand?"},"40:84":{"t":"Plötzlich: Wir glauben an Allah allein und verwerfen, was wir Ihm beigesellt haben. Genau das Gegenteil von dem, was sie früher taten (Vers 12).","q":"Hat ihnen dieser späte Glaube genützt?"},"40:85":{"t":"Nein, Glaube nützt nicht mehr, wenn man die Strafe schon sieht, das ist Allahs festes Gesetz unter Seinen Dienern. Und dort verloren die Ungläubigen (wie der Schluss von Vers 78).","q":""}},"pages":[{"n":1,"from":1,"to":7,"bridge":"","bridgeQ":"","thread":"Buchstaben → Absender des Buches → Seine Eigenschaften → die Streiter → ihre Vorgänger → ihr Urteil → der Gegenpol: die Engel beten für die Gläubigen."},{"n":2,"from":8,"to":16,"bridge":"In Vers 7 baten die Engel um Vergebung und Schutz vor der Hölle.","bridgeQ":"Reicht es, nur vor dem Schlimmen bewahrt zu werden?","thread":"Engel bitten ums Paradies → um Schutz vor Schlechtem → Gegenbild: Ungläubige verabscheuen sich → bitten um Ausweg → Grund: sie lehnten Tawḥīd ab → dabei zeigte Er ihnen Zeichen → also Ihn allein anrufen → denn Er ist erhaben und warnt vor dem Tag → an dem nur Ihm die Herrschaft gehört."},{"n":3,"from":17,"to":25,"bridge":"In Vers 16 wurde verkündet, dass an jenem Tag Allah allein die Herrschaft gehört.","bridgeQ":"Was folgt aus dieser Herrschaft?","thread":"Herrschaft → gerechter Lohn → warne vor dem nahenden Tag → Er weiß alles Verborgene → Götzen urteilen über nichts → schaut auf die Ruinen → Grund: Leugnung der Beweise → Beispiel Mūsā → gegen die drei Mächte → ihre Gewalt läuft ins Leere."},{"n":4,"from":26,"to":33,"bridge":"In Vers 25 scheiterte Firʿawns List, die Söhne der Gläubigen zu töten.","bridgeQ":"Was plant Firʿawn, als diese List nicht hilft?","thread":"Firʿawn will Mūsā töten → Mūsā sucht Zuflucht → Allah schickt den gläubigen Mann → „Lügt er, trifft es ihn“ → eure Macht hilft nicht → Firʿawns Machtwort → Warnung vor dem Tag der Gruppierungen → Nūḥ, ʿĀd, Ṯamūd → Tag des Rufens → Flucht ohne Schutz."},{"n":5,"from":34,"to":40,"bridge":"In Vers 30–31 warnte der Gläubige mit dem Schicksal ferner Völker wie ʿĀd und Ṯamūd.","bridgeQ":"Gibt es auch ein Beispiel aus der eigenen Geschichte Ägyptens?","thread":"Yūsuf und euer Zweifel → Streit ohne Beweis, versiegeltes Herz → Firʿawn: „Bau mir einen Turm“ → zu den Himmeln, doch „ich halte ihn für einen Lügner“ → Gläubiger: „Folgt mir, ich leite euch“ → Diesseits kurz, Jenseits bleibt → Böses gleich vergolten, Gutes ohne Abrechnung."},{"n":6,"from":41,"to":49,"bridge":"In Vers 40 stellte der Gläubige Gerechtigkeit und Barmherzigkeit im Jenseits gegenüber.","bridgeQ":"Wie fasst er am Ende seine ganze Rede zusammen?","thread":"Ich rufe zur Rettung, ihr zum Feuer → ihr ruft zum Unglauben, ich zum Allmächtigen, Allvergebenden → eure Götzen haben keinen Anspruch → ich übergebe meine Sache Allah → Allah rettet ihn, Firʿawns Sippe wird bestraft → morgens und abends dem Feuer vorgeführt → Mitläufer streiten mit den Hochmütigen → „Wir sind alle darin“ → Bitte an die Wächter um einen Tag."},{"n":7,"from":50,"to":58,"bridge":"In Vers 49 baten die Höllenbewohner die Wächter, Allah um einen Tag Erleichterung zu bitten.","bridgeQ":"Was antworten die Wächter?","thread":"„Kamen nicht eure Gesandten?“ → Allah steht Gesandten und Gläubigen bei → Entschuldigung nützt den Ungerechten nicht → Beispiel Mūsā und die Schrift → Rechtleitung für die Verständigen → also sei geduldig und preise → ihr Streit ist nur Hochmut → Himmel und Erde sind größer als der Mensch → Blinder und Sehender sind nicht gleich."},{"n":8,"from":59,"to":66,"bridge":"In Vers 57 hieß es, dass die Erschaffung der Himmel und der Erde größer ist als die Erschaffung der Menschen.","bridgeQ":"Was folgt daraus für die Auferstehung?","thread":"Die Stunde kommt sicher → „Ruft Mich an“ → Er gab Nacht und Tag → das ist Allah, der Schöpfer von allem → so wurden auch Frühere abgewendet → Erde, Himmel, schöne Gestalt, gute Versorgung → Er ist der Lebendige, ruft Ihn aufrichtig an → „Mir wurde verboten … und befohlen …“."},{"n":9,"from":67,"to":77,"bridge":"Auf Seite 8 ging es um die Zeichen im Kosmos: Nacht und Tag, Erde und Himmel.","bridgeQ":"Gibt es auch einen Beweis direkt im Menschen selbst?","thread":"Erde → Tropfen → Kind → Greis → „Sei!“ → Wie können sie da streiten? → sie leugnen Buch und Gesandte → Fesseln und Ketten → kochendes Wasser, dann Feuer → „Wo sind eure Götzen?“ → „Sie sind entschwunden“ → Grund: falsche Freude und Übermut → Tore der Hölle → sei geduldig."},{"n":10,"from":78,"to":85,"bridge":"In Vers 77 wurde der Prophet ﷺ getröstet: Sei geduldig, ob du ihre Strafe noch erlebst oder nicht.","bridgeQ":"Ging es früheren Gesandten genauso?","thread":"Gesandte vor dir, kein Wunder ohne Erlaubnis → Vieh zum Reiten und Essen → Nutzen, Land und Schiff → „Welche Zeichen wollt ihr leugnen?“ → schaut auf die früheren Völker → sie freuten sich über ihr Wissen → „Wir glauben an Allah allein“ → zu spät, dort verloren die Ungläubigen."}],"arc":"Die Sure beginnt mit dem „Vergeber der Sünde, Annehmer der Reue“ (Vers 3), solange Umkehr noch möglich ist, und endet mit einer Umkehr, die zu spät kommt (Vers 84–85). Dazwischen läuft das eine Thema: das Streiten über Allahs Zeichen aus Hochmut (Vers 4, 35, 56, 69) und sein Ende im Verlust."};
